  link_rules: { en: 'Rules & terms', ru: 'Правила', ar: 'القواعد والشروط', zh: '规则与条款', es: 'Reglas y términos', tr: 'Kurallar ve şartlar', pt: 'Regras e termos', fr: 'Règles et conditions', uk: 'Правила' },
