type I18nContextType = {
  lang: Lang
  setLang: (l: Lang) => void
  t: (key: keyof typeof DICT) => string
  dir: 'ltr' | 'rtl'
  ready: boolean
  needsLangSelect: boolean
  confirmLang: (l: Lang) => void
}

const I18nContext = createContext<I18nContextType | null>(null)

const STORAGE_KEY = 'xboost_lang'

export function I18nProvider({ children }: { children: React.ReactNode }) {
  const [lang, setLangState] = useState<Lang>('en')
  const [ready, setReady] = useState(false)
  const [needsLangSelect, setNeedsLangSelect] = useState(false)

  useEffect(() => {
    let saved: string | null = null
    try {
      saved = localStorage.getItem(STORAGE_KEY)
    } catch {}

    const VALID_LANGS: Lang[] = ['en', 'ru', 'ar', 'zh', 'es', 'tr', 'pt', 'fr', 'uk']
    if (saved && VALID_LANGS.includes(saved as Lang)) {
      setLangState(saved as Lang)
      setReady(true)
      return
    }


    // Try Telegram language auto-detection on first launch
    const tg = (typeof window !== 'undefined' && (window as any).Telegram?.WebApp) || null
    const tgLang: string | undefined = tg?.initDataUnsafe?.user?.language_code
    if (tgLang) {
      const code = tgLang.toLowerCase()
      const mapped: Lang | null =
        code.startsWith('ru') ? 'ru' :
        code.startsWith('ar') ? 'ar' :
        code.startsWith('zh') ? 'zh' :
        code.startsWith('en') ? 'en' :
        code.startsWith('es') ? 'es' :
        code.startsWith('tr') ? 'tr' :
        code.startsWith('pt') ? 'pt' :
        code.startsWith('fr') ? 'fr' :
        code.startsWith('uk') ? 'uk' : null
      if (mapped) {
        setLangState(mapped)
        try {
          localStorage.setItem(STORAGE_KEY, mapped)
        } catch {}
        setReady(true)
        return
      }
    }

    // No saved choice and no recognizable TG language -> ask once
    setNeedsLangSelect(true)
    setReady(true)
  }, [])

  const setLang = useCallback((l: Lang) => {
    setLangState(l)
    try {
      localStorage.setItem(STORAGE_KEY, l)
    } catch {}
  }, [])

  const confirmLang = useCallback((l: Lang) => {
    setLang(l)
    setNeedsLangSelect(false)
  }, [setLang])

  const dir: 'ltr' | 'rtl' = lang === 'ar' ? 'rtl' : 'ltr'

  useEffect(() => {
    if (typeof document !== 'undefined') {
      document.documentElement.lang = lang
      document.documentElement.dir = dir
    }
  }, [lang, dir])

  const t = useCallback(
    (key: keyof typeof DICT) => DICT[key]?.[lang] ?? String(key),
    [lang],
  )

  const value = useMemo(
    () => ({ lang, setLang, t, dir, ready, needsLangSelect, confirmLang }),
    [lang, setLang, t, dir, ready, needsLangSelect, confirmLang],
  )

  return <I18nContext.Provider value={value}>{children}</I18nContext.Provider>
}

export function useI18n() {
  const ctx = useContext(I18nContext)
  if (!ctx) throw new Error('useI18n must be used within I18nProvider')
  return ctx
}
